n=int(lines[0]); at=[]
for L in lines[2:2+n]:
    s=L.split(); at.append((s[0],np.array([float(s[1]),float(s[2]),float(s[3])])))
cov={'C':0.76,'N':0.71,'Ge':1.20,'Au':1.36,'H':0.31}
heavy=[(i,e,x) for i,(e,x) in enumerate(at) if e!='H']
bonds=set()
for a in range(len(heavy)):
    for b in range(a+1,len(heavy)):
        i,e1,x1=heavy[a]; j,e2,x2=heavy[b]
        if np.linalg.norm(x1-x2) < cov[e1]+cov[e2]+0.25: bonds.add((i,j))
for gi in [i for i,e,x in heavy if e=='Ge']:
    nb=sorted([(j,at[j][0],round(float(np.linalg.norm(at[gi][1]-at[j][1])),3)) for (a,j) in bonds if a==gi]+[(a,at[a][0],round(float(np.linalg.norm(at[gi][1]-at[a][1])),3)) for (a,j) in bonds if j==gi], key=lambda t:t[2])
    print('Ge',gi,'->',nb)
for ai in [i for i,e,x in heavy if e=='Au']:
    nb=[(j,at[j][0],round(float(np.linalg.norm(at[ai][1]-at[j][1])),3)) for (a,j) in bonds if a==ai]+[(a,at[a][0],round(float(np.linalg.norm(at[ai][1]-at[a][1])),3)) for (a,j) in bonds if j==ai]
    print('Au',ai,'->',nb)
# shortest nonbonded contacts involving H
mind=9;mp=None
for i,(e1,x1) in enumerate(at):
    for j in range(i+1,len(at)):
        e2,x2=at[j]
        if (i,j) in bonds or (j,i) in bonds: continue
        d=np.linalg.norm(x1-x2)
        if d<mind: mind=d;mp=(i,e1,j,e2)
print('shortest nonbonded any-atom contact:',round(mind,3),mp)
# count bonds (sanity): ligand should have expected bond count
print('num heavy-heavy bonds (dist-based):',len(bonds))
